/**
 * Heroes' Feast DAE Item Macro — v10+/v12+兼容，严格删除中毒/疾病状态
 * - DAE 创建 effect 时调用： args[0] === "on"
 * - DAE 删除 effect 时调用： args[0] === "off"
 */
(async () => {
  const DEBUG = true;
  const DBG = (...m) => { if (DEBUG) console.log("HF_DAE_DBG:", ...m); };

  try {
    DBG("ENTRY (final): typeof args:", typeof args, "args:", args);

    // 支持手动运行用于调试
    if (typeof args === "undefined") {
      const sel = canvas.tokens.controlled[0];
      if (!sel) return ui.notifications.warn("请先选中一个 Token 以手动测试该宏，或由 DAE 触发。");
      const actorUuid = sel.actor?.uuid;
      args = ["on", actorUuid, { actorUuid }];
      DBG("Manual-run: synthesized args:", args);
    }

    const mode = args[0];
    DBG("mode:", mode);

    // 解析目标 actor/token
    async function resolveTarget() {
      if (typeof actor !== "undefined" && actor) return { actor, token: (typeof token !== "undefined") ? token : null };
      const lastArg = args[args.length - 1] ?? {};
      if (lastArg?.tokenUuid) {
        try { const tokDoc = await fromUuid(lastArg.tokenUuid); if (tokDoc?.object) return { actor: tokDoc.object.actor, token: tokDoc.object }; } catch(e){ DBG("fromUuid(tokenUuid) threw:", e); }
      }
      if (lastArg?.actorUuid) {
        try { const aDoc = await fromUuid(lastArg.actorUuid); if (aDoc?.actor) return { actor: aDoc.actor, token: null }; if (aDoc) return { actor: aDoc, token: null }; } catch(e){ DBG("fromUuid(actorUuid) threw:", e); }
      }
      for (let i = 1; i < Math.min(args.length, 6); i++) {
        try {
          if (typeof args[i] === "string" && (args[i].startsWith("Actor."))) {
            const a = await fromUuid(args[i]);
            if (a?.actor) return { actor: a.actor, token: null };
            if (a) return { actor: a, token: null };
          }
        } catch (e) { DBG("fromUuid(args[i]) threw:", e); }
      }
      try { const ctrl = canvas.tokens.controlled; if (ctrl?.length >= 1) return { actor: ctrl[0].actor, token: ctrl[0] }; } catch(e){ DBG("canvas.tokens.controlled access threw:", e); }
      return { actor: null, token: null };
    }

    const resolved = await resolveTarget();
    let targetActor = resolved.actor;
    const targetToken = resolved.token;
    if (!targetActor) {
      DBG("resolveTarget failed:", resolved);
      return ui.notifications.error("Heroes' Feast: 无法解析目标 Actor，请检查 DAE macro.execute 或 选中 Token。");
    }
    DBG("Resolved targetActor:", targetActor.name ?? targetActor.id);
    if (typeof targetActor.getFlag !== "function" && targetActor.actor) targetActor = targetActor.actor;
    if (typeof targetActor.getFlag !== "function") return ui.notifications.error("Heroes' Feast: targetActor 对象类型不符合预期。");

    // effect key
    const lastArg = args[args.length - 1] ?? {};
    let effectKey = lastArg.effectId || lastArg.origin || lastArg.uuid || lastArg.itemUuid || null;
    if (!effectKey && typeof args[1] === "string" && args[1].startsWith("Actor")) effectKey = args[1];
    if (!effectKey) effectKey = `heroesFeast_${Date.now()}`;
    DBG("effectKey:", effectKey);

    // helpers
    function aeName(eff) { return (eff?.name) ?? (eff?.system?.name) ?? (eff?.data?.name) ?? (eff?.label) ?? ""; }
    const fget = foundry.utils.getProperty;
    const FLAG_SCOPE = "world";
    const FLAG_PATH = "heroesFeast.bonuses";

    // ----- ON -----
    if (mode === "on") {
      DBG("ON branch: rolling 2d10");
      let bonus = 0;
      try {
        const r = await new Roll("2d10").roll();
        if (game?.dice3d) await game.dice3d.showForRoll(r);
        bonus = Number(r.total || 0);
      } catch (e) { bonus = 0; DBG("roll error:", e); }

      try {
        const curMax = Number(fget(targetActor, "system.attributes.hp.max") || 0);
        const curVal = Number(fget(targetActor, "system.attributes.hp.value") || 0);
        await targetActor.update({ "system.attributes.hp.max": curMax + bonus, "system.attributes.hp.value": curVal + bonus });
        DBG("Actor HP updated:", curVal + bonus, "/", curMax + bonus);
      } catch (e) { DBG("actor.update failed (ON):", e); }

      // 保存 flag
      try {
        let arr = await targetActor.getFlag(FLAG_SCOPE, FLAG_PATH) || [];
        arr.push({ key: effectKey, bonus, ts: Date.now() });
        await targetActor.setFlag(FLAG_SCOPE, FLAG_PATH, arr);
      } catch(e){ DBG("setFlag failed (ON):", e); }

      // 严格删除中毒/疾病（系统自带 + 汉化 mod）
      try {
        const toRemove = targetActor.effects.filter(e => {
          const name = (aeName(e) || "").trim();
          return ["中毒", "疾病", "Poisoned", "Diseased"].includes(name);
        });
        if (toRemove.length) {
          const ids = toRemove.map(e => e.id);
          await targetActor.deleteEmbeddedDocuments("ActiveEffect", ids);
          DBG("Removed strict-status disease/poison effects:", ids);
        }
      } catch (e) { DBG("strict-status disease removal error (ON):", e); }

      ChatMessage.create({ content: `${targetActor.name} 受到了 <strong>英雄宴 / Heroes' Feast</strong> 的祝福：生命值上限与当前生命值各增加 <strong>${bonus}</strong> 点，并清除已识别的疾病/中毒状态。` });
      return;
    }

    // ----- OFF -----
    if (mode === "off") {
      DBG("OFF branch: withdrawing for key:", effectKey);
      let arr = await targetActor.getFlag(FLAG_SCOPE, FLAG_PATH) || [];
      let idx = arr.findIndex(x => x.key === effectKey);
      if (idx === -1 && arr.length > 0) idx = arr.length - 1;
      if (idx === -1) { DBG("No stored bonus to withdraw (OFF)."); return; }

      const rec = arr[idx];
      const withdraw = Number(rec.bonus || 0);
      DBG("Withdrawing rec:", rec);

      try {
        const curMax = Number(fget(targetActor, "system.attributes.hp.max") || 0);
        const curVal = Number(fget(targetActor, "system.attributes.hp.value") || 0);
        await targetActor.update({ "system.attributes.hp.max": Math.max(0, curMax - withdraw), "system.attributes.hp.value": Math.min(curVal, curMax - withdraw) });
      } catch (e) { DBG("actor.update failed (OFF):", e); }

      // 移除 flag
      arr.splice(idx,1);
      if (arr.length) await targetActor.setFlag(FLAG_SCOPE, FLAG_PATH, arr);
      else await targetActor.unsetFlag(FLAG_SCOPE, FLAG_PATH);

      ChatMessage.create({ content: `${targetActor.name} 的 <strong>英雄宴 / Heroes' Feast</strong> 效果结束：生命值上限减少 <strong>${withdraw}</strong> 点。` });
      return;
    }

    DBG("Mode not recognized:", mode);

  } catch (err) {
    console.error("HF_DAE_DBG: Top-level macro error:", err, err?.stack);
    throw err;
  }
})();
